// ---- dates.js ----
// Date handling. All dates are date-only ISO strings 'YYYY-MM-DD'.
// All arithmetic is done in UTC so the host timezone can never shift a day.
// Nothing here throws: bad input gives null.

const ISO_RE = /^(\d{4})-(\d{2})-(\d{2})$/;
const UK_RE = /^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{4})$/;
const MS_PER_DAY = 86400000;

/** Build a UTC timestamp from y/m/d, or null if the calendar date is not real. */
function utcFromParts(y, m, d) {
  if (!Number.isInteger(y) || !Number.isInteger(m) || !Number.isInteger(d)) return null;
  if (y < 1000 || y > 9999 || m < 1 || m > 12 || d < 1 || d > 31) return null;
  const ts = Date.UTC(y, m - 1, d);
  const dt = new Date(ts);
  // Rejects 31 February style overflow, which JS would otherwise roll forward.
  if (dt.getUTCFullYear() !== y || dt.getUTCMonth() !== m - 1 || dt.getUTCDate() !== d) return null;
  return ts;
}

/** Format a UTC timestamp as 'YYYY-MM-DD'. */
function toISO(ts) {
  const d = new Date(ts);
  const p = (n) => String(n).padStart(2, '0');
  return `${d.getUTCFullYear()}-${p(d.getUTCMonth() + 1)}-${p(d.getUTCDate())}`;
}

/**
 * Parse a spreadsheet cell or API value into 'YYYY-MM-DD'.
 * Accepts ISO strings, UK dd/mm/yyyy, JS Dates and Google Sheets serial numbers.
 * Returns null rather than guessing when the value is ambiguous or invalid.
 * Never uses `new Date(string)`, whose parsing is locale-dependent.
 */
function parseSheetDate(value) {
  if (value === null || value === undefined) return null;

  if (value instanceof Date) {
    if (Number.isNaN(value.getTime())) return null;
    return toISO(Date.UTC(value.getUTCFullYear(), value.getUTCMonth(), value.getUTCDate()));
  }

  // Google Sheets serial: days since 1899-12-30.
  if (typeof value === 'number') {
    if (!Number.isFinite(value) || value < 1 || value > 100000) return null;
    return toISO(Date.UTC(1899, 11, 30) + Math.floor(value) * MS_PER_DAY);
  }

  const s = String(value).trim();
  if (s === '') return null;

  const iso = ISO_RE.exec(s);
  if (iso) {
    const ts = utcFromParts(+iso[1], +iso[2], +iso[3]);
    return ts === null ? null : toISO(ts);
  }

  const uk = UK_RE.exec(s);
  if (uk) {
    const ts = utcFromParts(+uk[3], +uk[2], +uk[1]);
    return ts === null ? null : toISO(ts);
  }

  return null;
}

/** Timestamp for an ISO date string, or null. */
function tsOf(isoDate) {
  const m = ISO_RE.exec(String(isoDate ?? '').trim());
  if (!m) return null;
  return utcFromParts(+m[1], +m[2], +m[3]);
}

/** Whole days from `from` to `to`. Positive when `to` is later. */
function daysBetween(fromISO, toISOdate) {
  const a = tsOf(fromISO);
  const b = tsOf(toISOdate);
  if (a === null || b === null) return null;
  return Math.round((b - a) / MS_PER_DAY);
}

function addDays(isoDate, n) {
  const ts = tsOf(isoDate);
  if (ts === null || !Number.isFinite(n)) return null;
  return toISO(ts + n * MS_PER_DAY);
}

/** 0 = Sunday .. 6 = Saturday */
function dayOfWeek(isoDate) {
  const ts = tsOf(isoDate);
  return ts === null ? null : new Date(ts).getUTCDay();
}

function daysInMonth(y, m) {
  return new Date(Date.UTC(y, m, 0)).getUTCDate();
}

function isLastDayOfMonth(isoDate) {
  const ts = tsOf(isoDate);
  if (ts === null) return false;
  const d = new Date(ts);
  return d.getUTCDate() === daysInMonth(d.getUTCFullYear(), d.getUTCMonth() + 1);
}

function lastDayOfMonthOf(isoDate) {
  const ts = tsOf(isoDate);
  if (ts === null) return null;
  const d = new Date(ts);
  const y = d.getUTCFullYear();
  const m = d.getUTCMonth() + 1;
  return toISO(Date.UTC(y, m - 1, daysInMonth(y, m)));
}

/**
 * Add whole calendar months the way Companies House describes them: a period of
 * months after a date ends on the corresponding date in the appropriate month
 * (4 April + 9 months is 4 January). When `monthEndSticky` is true, a date that
 * is the last day of its month ends on the last day of the appropriate month
 * (30 April + 9 months is 31 January). The guidance states that second rule for
 * accounting reference dates only, so callers pass true for those and nothing else.
 *
 * Returns { date, clamped }. `clamped` is true when the corresponding date does
 * not exist in the target month (31 May + 9 months) and the last day of that
 * month was used instead. That case is not covered by the guidance, so callers
 * flag it for a person to confirm. Returns { date: null, clamped: false } for
 * bad input.
 */
function addMonths(isoDate, months, monthEndSticky = false) {
  const ts = tsOf(isoDate);
  if (ts === null || !Number.isInteger(months)) return { date: null, clamped: false };
  const src = new Date(ts);
  const y = src.getUTCFullYear();
  const m0 = src.getUTCMonth();
  const d = src.getUTCDate();
  const total = y * 12 + m0 + months;
  const ty = Math.floor(total / 12);
  const tm = (total % 12 + 12) % 12 + 1;
  const dim = daysInMonth(ty, tm);
  if (ty < 1000 || ty > 9999) return { date: null, clamped: false };
  if (monthEndSticky === true && isLastDayOfMonth(isoDate)) {
    return { date: toISO(Date.UTC(ty, tm - 1, dim)), clamped: false };
  }
  if (d > dim) return { date: toISO(Date.UTC(ty, tm - 1, dim)), clamped: true };
  return { date: toISO(Date.UTC(ty, tm - 1, d)), clamped: false };
}

/** 'Wednesday 14 October 2026', how a UK practice reads a date. */
function formatUKDate(isoDate) {
  const ts = tsOf(isoDate);
  if (ts === null) return String(isoDate ?? '');
  const days = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
  const months = ['January', 'February', 'March', 'April', 'May', 'June',
    'July', 'August', 'September', 'October', 'November', 'December'];
  const d = new Date(ts);
  return `${days[d.getUTCDay()]} ${d.getUTCDate()} ${months[d.getUTCMonth()]} ${d.getUTCFullYear()}`;
}

// ---- companies.js ----
// Reading a client row and a Companies House response into clean values.
// Nothing here throws. Anything unusable is returned as null with a reason,
// so the planner can flag it instead of guessing.

const EMAIL_RE = /^[^\s@]+@[^\s@.]+(\.[^\s@.]+)+$/;
const COMPANY_NUMBER_RE = /^[A-Z0-9]{2}\d{6}$/;

function isValidEmail(value) {
  const s = String(value ?? '').trim();
  return s.length > 0 && s.length <= 254 && EMAIL_RE.test(s);
}

/**
 * Companies House numbers are eight characters: two letters or digits then six
 * digits (SC123456, 01234567). A spreadsheet often drops leading zeros from an
 * all-digit number, so those are padded back to eight and reported as padded.
 */
function normaliseCompanyNumber(value) {
  const raw = String(value ?? '').replace(/\s+/g, '').toUpperCase();
  if (raw === '') return { number: '', valid: false, padded: false, reason: 'no company number' };
  if (/^\d{1,7}$/.test(raw)) {
    return { number: raw.padStart(8, '0'), valid: true, padded: true, reason: null };
  }
  if (COMPANY_NUMBER_RE.test(raw)) return { number: raw, valid: true, padded: false, reason: null };
  return { number: raw, valid: false, padded: false, reason: `"${raw}" is not a Companies House number` };
}

/** 'private' | 'public' | null, using the synonym lists held in the rules file. */
function normaliseCompanyType(value, rules) {
  const s = String(value ?? '').trim().toLowerCase().replace(/\s+/g, ' ');
  if (s === '') return null;
  const lists = (rules && rules.companyType) || {};
  if (Array.isArray(lists.private) && lists.private.includes(s)) return 'private';
  if (Array.isArray(lists.public) && lists.public.includes(s)) return 'public';
  return null;
}

/** Companies House API company type, narrower than the sheet: unknown types are not guessed. */
function typeFromApi(apiType) {
  const s = String(apiType ?? '').trim().toLowerCase();
  if (s === 'ltd') return 'private';
  if (s === 'plc') return 'public';
  return null;
}

function truthy(value) {
  const s = String(value ?? '').trim().toLowerCase();
  return s === 'yes' || s === 'y' || s === 'true' || s === '1' || s === 'paused';
}

const COLUMNS = {
  name: 'Company Name',
  number: 'Company Number',
  type: 'Company Type',
  incorporated: 'Incorporation Date',
  lastAccounts: 'Last Accounts Made Up To',
  periodEnd: 'Next Accounts Period End',
  lastCs: 'Last Confirmation Statement Made Up To',
  csDue: 'Confirmation Statement Due',
  accountsDue: 'Accounts Due',
  email: 'Client Contact Email',
  paused: 'Paused',
};

const COMPANY_COLUMNS = COLUMNS;

function isEmptyRow(row) {
  if (!row || typeof row !== 'object') return true;
  return Object.entries(row).every(([k, v]) =>
    k === 'row_number' || k.startsWith('_') || String(v ?? '').trim() === '');
}

/**
 * One sheet row as typed values. `problems` lists every date cell that has text
 * in it but cannot be read, because a date that silently becomes "missing" is
 * how a deadline gets lost.
 */
function readCompanyRow(row, rules) {
  const r = row && typeof row === 'object' ? row : {};
  const problems = [];
  const date = (key) => {
    const raw = r[COLUMNS[key]];
    if (raw === undefined || raw === null || String(raw).trim() === '') return null;
    const parsed = parseSheetDate(raw);
    if (parsed === null) problems.push(`${COLUMNS[key]} "${String(raw).trim()}" is not a readable date`);
    return parsed;
  };
  const num = normaliseCompanyNumber(r._companyNumber !== undefined ? r._companyNumber : r[COLUMNS.number]);
  const typeRaw = String(r[COLUMNS.type] ?? '').trim();
  const type = normaliseCompanyType(typeRaw, rules);
  if (typeRaw !== '' && type === null) problems.push(`Company Type "${typeRaw}" is not recognised (use Private or Public)`);

  return {
    rowNumber: Number.isFinite(r.row_number) ? r.row_number : null,
    name: String(r[COLUMNS.name] ?? '').trim(),
    number: num,
    type,
    incorporated: date('incorporated'),
    lastAccounts: date('lastAccounts'),
    periodEnd: date('periodEnd'),
    lastCs: date('lastCs'),
    csDueOverride: date('csDue'),
    accountsDueOverride: date('accountsDue'),
    email: String(r[COLUMNS.email] ?? '').trim(),
    paused: truthy(r[COLUMNS.paused]),
    problems,
  };
}

function apiDate(v) {
  const s = parseSheetDate(typeof v === 'string' ? v : null);
  return s;
}

/**
 * The parts of a Companies House company profile this kit uses.
 * `ok` is false for a failed lookup (an error object, a 404 body, nothing at
 * all), in which case the sheet is the only source and the planner says so.
 */
function readApiProfile(api) {
  const none = { ok: false, reason: 'no response from Companies House' };
  if (!api || typeof api !== 'object') return none;
  if (api.error || api.errors || api.message) {
    const why = api.error?.message || api.message || (typeof api.error === 'string' ? api.error : 'lookup failed');
    return { ok: false, reason: `Companies House lookup failed: ${String(why).slice(0, 120)}` };
  }
  if (typeof api.company_number !== 'string' && typeof api.company_status !== 'string') {
    return { ok: false, reason: 'Companies House returned an unexpected response' };
  }
  const acc = api.accounts && typeof api.accounts === 'object' ? api.accounts : {};
  const cs = api.confirmation_statement && typeof api.confirmation_statement === 'object'
    ? api.confirmation_statement : {};
  return {
    ok: true,
    reason: null,
    number: typeof api.company_number === 'string' ? api.company_number.toUpperCase() : '',
    name: typeof api.company_name === 'string' ? api.company_name : '',
    status: typeof api.company_status === 'string' ? api.company_status.toLowerCase() : '',
    type: typeFromApi(api.type),
    rawType: typeof api.type === 'string' ? api.type : '',
    incorporated: apiDate(api.date_of_creation),
    accounts: {
      nextDue: apiDate(acc.next_due),
      nextMadeUpTo: apiDate(acc.next_made_up_to),
      lastMadeUpTo: apiDate(acc.last_accounts && acc.last_accounts.made_up_to),
      overdue: acc.overdue === true,
    },
    confirmationStatement: {
      nextDue: apiDate(cs.next_due),
      nextMadeUpTo: apiDate(cs.next_made_up_to),
      lastMadeUpTo: apiDate(cs.last_made_up_to),
      overdue: cs.overdue === true,
    },
  };
}

// ---- n8n entry point ----
// Adds a cleaned company number to each row so the lookup URL is built from the
// same normalisation the planner uses. Every row is kept, including bad ones,
// so the planner can report them.
// Paused and unusable rows skip the lookup.
return $input.all().map((item, index) => {
  const num = normaliseCompanyNumber(item.json['Company Number']);
  const paused = readCompanyRow(item.json, null).paused;
  return {
    json: { ...item.json, _companyNumber: num.number, _needsLookup: num.valid && !paused },
    pairedItem: { item: index },
  };
});

