// ---- rules.js ----
// Interpreting the rules file and the reminder calendar. The numbers themselves
// (months, days, status lists) live in ../../rules/deadline-rules.json and are
// cited in ../../rules/RULES.md. Nothing here throws.

/** Returns a list of problems with a rules object. Empty means usable. */
function rulesProblems(rules) {
  const out = [];
  const isNum = (v) => Number.isInteger(v) && v >= 0;
  if (!rules || typeof rules !== 'object') return ['rules are missing'];
  const a = rules.accounts || {};
  const f = a.firstAccounts || {};
  const c = rules.confirmationStatement || {};
  if (!isNum(a.privateMonthsAfterPeriodEnd)) out.push('accounts.privateMonthsAfterPeriodEnd');
  if (!isNum(a.publicMonthsAfterPeriodEnd)) out.push('accounts.publicMonthsAfterPeriodEnd');
  if (!isNum(a.standardPeriodMonths)) out.push('accounts.standardPeriodMonths');
  if (!isNum(f.privateMonthsAfterIncorporation)) out.push('accounts.firstAccounts.privateMonthsAfterIncorporation');
  if (!isNum(f.publicMonthsAfterIncorporation)) out.push('accounts.firstAccounts.publicMonthsAfterIncorporation');
  if (!isNum(f.minimumMonthsAfterPeriodEnd)) out.push('accounts.firstAccounts.minimumMonthsAfterPeriodEnd');
  if (!isNum(c.reviewPeriodMonths)) out.push('confirmationStatement.reviewPeriodMonths');
  if (!isNum(c.filingDaysAfterReviewPeriodEnd)) out.push('confirmationStatement.filingDaysAfterReviewPeriodEnd');
  if (!rules.companyStatus || !Array.isArray(rules.companyStatus.remindFor)
    || !Array.isArray(rules.companyStatus.suppress)) out.push('companyStatus');
  return out.map((p) => `rules file is missing or invalid: ${p}`);
}

/**
 * Which reminder band a deadline is in.
 * Milestones are days before the deadline, e.g. [30, 14, 7, 1]. The band is the
 * smallest milestone that is still at or above the days remaining, so a run that
 * was missed (n8n down, a weekend off) still produces the reminder the next time
 * it runs, instead of skipping a milestone for ever. Returns null when the
 * deadline is further away than the first milestone.
 *
 * A deadline already passed is `overdue-N`, where N steps up every
 * `overdueRepeatDays` so a late filing keeps surfacing without a daily flood.
 */
function bandFor(daysRemaining, milestones, overdueRepeatDays) {
  if (!Number.isFinite(daysRemaining) || !Array.isArray(milestones)) return null;
  if (daysRemaining < 0) {
    const repeat = Number.isInteger(overdueRepeatDays) && overdueRepeatDays > 0 ? overdueRepeatDays : 7;
    const n = Math.floor((-daysRemaining - 1) / repeat) + 1;
    return { band: `overdue-${n}`, overdue: true };
  }
  const ascending = [...milestones].sort((x, y) => x - y);
  const m = ascending.find((x) => x >= daysRemaining);
  if (m === undefined) return null;
  return { band: String(m), overdue: false };
}

/** 'remind' | 'suppress' | 'review' for a Companies House company status. */
function statusAction(status, rules) {
  const s = String(status ?? '').trim().toLowerCase();
  const st = (rules && rules.companyStatus) || {};
  if ((st.remindFor || []).includes(s)) return 'remind';
  if ((st.suppress || []).includes(s)) return 'suppress';
  return 'review';
}

const KIND_LABEL = {
  accounts: 'Annual accounts',
  confirmationStatement: 'Confirmation statement',
};

// ---- companies.js ----
// Reading a client row and a Companies House response into clean values.
// Nothing here throws. Anything unusable is returned as null with a reason,
// so the planner can flag it instead of guessing.

const EMAIL_RE = /^[^\s@]+@[^\s@.]+(\.[^\s@.]+)+$/;
const COMPANY_NUMBER_RE = /^[A-Z0-9]{2}\d{6}$/;

function isValidEmail(value) {
  const s = String(value ?? '').trim();
  return s.length > 0 && s.length <= 254 && EMAIL_RE.test(s);
}

/**
 * Companies House numbers are eight characters: two letters or digits then six
 * digits (SC123456, 01234567). A spreadsheet often drops leading zeros from an
 * all-digit number, so those are padded back to eight and reported as padded.
 */
function normaliseCompanyNumber(value) {
  const raw = String(value ?? '').replace(/\s+/g, '').toUpperCase();
  if (raw === '') return { number: '', valid: false, padded: false, reason: 'no company number' };
  if (/^\d{1,7}$/.test(raw)) {
    return { number: raw.padStart(8, '0'), valid: true, padded: true, reason: null };
  }
  if (COMPANY_NUMBER_RE.test(raw)) return { number: raw, valid: true, padded: false, reason: null };
  return { number: raw, valid: false, padded: false, reason: `"${raw}" is not a Companies House number` };
}

/** 'private' | 'public' | null, using the synonym lists held in the rules file. */
function normaliseCompanyType(value, rules) {
  const s = String(value ?? '').trim().toLowerCase().replace(/\s+/g, ' ');
  if (s === '') return null;
  const lists = (rules && rules.companyType) || {};
  if (Array.isArray(lists.private) && lists.private.includes(s)) return 'private';
  if (Array.isArray(lists.public) && lists.public.includes(s)) return 'public';
  return null;
}

/** Companies House API company type, narrower than the sheet: unknown types are not guessed. */
function typeFromApi(apiType) {
  const s = String(apiType ?? '').trim().toLowerCase();
  if (s === 'ltd') return 'private';
  if (s === 'plc') return 'public';
  return null;
}

function truthy(value) {
  const s = String(value ?? '').trim().toLowerCase();
  return s === 'yes' || s === 'y' || s === 'true' || s === '1' || s === 'paused';
}

const COLUMNS = {
  name: 'Company Name',
  number: 'Company Number',
  type: 'Company Type',
  incorporated: 'Incorporation Date',
  lastAccounts: 'Last Accounts Made Up To',
  periodEnd: 'Next Accounts Period End',
  lastCs: 'Last Confirmation Statement Made Up To',
  csDue: 'Confirmation Statement Due',
  accountsDue: 'Accounts Due',
  email: 'Client Contact Email',
  paused: 'Paused',
};

const COMPANY_COLUMNS = COLUMNS;

function isEmptyRow(row) {
  if (!row || typeof row !== 'object') return true;
  return Object.entries(row).every(([k, v]) =>
    k === 'row_number' || k.startsWith('_') || String(v ?? '').trim() === '');
}

/**
 * One sheet row as typed values. `problems` lists every date cell that has text
 * in it but cannot be read, because a date that silently becomes "missing" is
 * how a deadline gets lost.
 */
function readCompanyRow(row, rules) {
  const r = row && typeof row === 'object' ? row : {};
  const problems = [];
  const date = (key) => {
    const raw = r[COLUMNS[key]];
    if (raw === undefined || raw === null || String(raw).trim() === '') return null;
    const parsed = parseSheetDate(raw);
    if (parsed === null) problems.push(`${COLUMNS[key]} "${String(raw).trim()}" is not a readable date`);
    return parsed;
  };
  const num = normaliseCompanyNumber(r._companyNumber !== undefined ? r._companyNumber : r[COLUMNS.number]);
  const typeRaw = String(r[COLUMNS.type] ?? '').trim();
  const type = normaliseCompanyType(typeRaw, rules);
  if (typeRaw !== '' && type === null) problems.push(`Company Type "${typeRaw}" is not recognised (use Private or Public)`);

  return {
    rowNumber: Number.isFinite(r.row_number) ? r.row_number : null,
    name: String(r[COLUMNS.name] ?? '').trim(),
    number: num,
    type,
    incorporated: date('incorporated'),
    lastAccounts: date('lastAccounts'),
    periodEnd: date('periodEnd'),
    lastCs: date('lastCs'),
    csDueOverride: date('csDue'),
    accountsDueOverride: date('accountsDue'),
    email: String(r[COLUMNS.email] ?? '').trim(),
    paused: truthy(r[COLUMNS.paused]),
    problems,
  };
}

function apiDate(v) {
  const s = parseSheetDate(typeof v === 'string' ? v : null);
  return s;
}

/**
 * The parts of a Companies House company profile this kit uses.
 * `ok` is false for a failed lookup (an error object, a 404 body, nothing at
 * all), in which case the sheet is the only source and the planner says so.
 */
function readApiProfile(api) {
  const none = { ok: false, reason: 'no response from Companies House' };
  if (!api || typeof api !== 'object') return none;
  if (api.error || api.errors || api.message) {
    const why = api.error?.message || api.message || (typeof api.error === 'string' ? api.error : 'lookup failed');
    return { ok: false, reason: `Companies House lookup failed: ${String(why).slice(0, 120)}` };
  }
  if (typeof api.company_number !== 'string' && typeof api.company_status !== 'string') {
    return { ok: false, reason: 'Companies House returned an unexpected response' };
  }
  const acc = api.accounts && typeof api.accounts === 'object' ? api.accounts : {};
  const cs = api.confirmation_statement && typeof api.confirmation_statement === 'object'
    ? api.confirmation_statement : {};
  return {
    ok: true,
    reason: null,
    number: typeof api.company_number === 'string' ? api.company_number.toUpperCase() : '',
    name: typeof api.company_name === 'string' ? api.company_name : '',
    status: typeof api.company_status === 'string' ? api.company_status.toLowerCase() : '',
    type: typeFromApi(api.type),
    rawType: typeof api.type === 'string' ? api.type : '',
    incorporated: apiDate(api.date_of_creation),
    accounts: {
      nextDue: apiDate(acc.next_due),
      nextMadeUpTo: apiDate(acc.next_made_up_to),
      lastMadeUpTo: apiDate(acc.last_accounts && acc.last_accounts.made_up_to),
      overdue: acc.overdue === true,
    },
    confirmationStatement: {
      nextDue: apiDate(cs.next_due),
      nextMadeUpTo: apiDate(cs.next_made_up_to),
      lastMadeUpTo: apiDate(cs.last_made_up_to),
      overdue: cs.overdue === true,
    },
  };
}

// ---- deadlines.js ----
// The deadline arithmetic. Every rule it applies is a value in rules/deadline-rules.json
// and a row in rules/RULES.md. It returns a result for every input, including bad
// input: a deadline it cannot work out comes back with dueDate null and the reason
// in `flags`, never an exception and never a guess.

const SHEET_ONLY_FLAG = 'Worked out from the sheet, not taken from Companies House. Needs human confirmation against the register.';

function finish(kind, dueDate, source, periodEnd, flags, notes, overdueAtRegister) {
  return {
    kind,
    dueDate: dueDate || null,
    source: dueDate ? source : 'none',
    periodEnd: periodEnd || null,
    flags,
    notes,
    overdueAtRegister: overdueAtRegister === true,
    discrepancy: false,
    needsConfirmation: flags.length > 0,
  };
}

/** Pick between the Companies House date, the date typed into the sheet, and the calculation. */
function choose(kind, apiDue, sheetDue, calc, periodEnd, overdueAtRegister) {
  const flags = [];
  const notes = [];
  if (apiDue && sheetDue && apiDue !== sheetDue) {
    flags.push(`Companies House says ${apiDue} but the sheet says ${sheetDue}. The earlier date is used. Needs human confirmation.`);
    const result = finish(kind, apiDue < sheetDue ? apiDue : sheetDue, 'companies-house', periodEnd, flags, notes, overdueAtRegister);
    result.discrepancy = true;
    return result;
  }
  if (apiDue) return finish(kind, apiDue, 'companies-house', periodEnd, flags, notes, overdueAtRegister);
  if (sheetDue) {
    flags.push('Date typed into the sheet and not cross-checked with Companies House. Needs human confirmation.');
    return finish(kind, sheetDue, 'sheet', periodEnd, flags, notes, overdueAtRegister);
  }
  if (calc && calc.date) {
    flags.push(SHEET_ONLY_FLAG, ...calc.flags);
    notes.push(...calc.notes);
    return finish(kind, calc.date, 'calculated', calc.periodEnd || periodEnd, flags, notes, overdueAtRegister);
  }
  flags.push(...((calc && calc.flags) || ['Not enough information to work out this deadline. Needs human confirmation.']));
  return finish(kind, null, 'none', periodEnd, flags, notes, overdueAtRegister);
}

/**
 * Accounts deadline.
 * @param {object} company  readCompanyRow() output
 * @param {object} profile  readApiProfile() output (ok false when the lookup failed)
 * @param {string|null} type 'private' | 'public' | null, already resolved by the planner
 * @param {object} rules    rules/deadline-rules.json
 */
function accountsDeadline(company, profile, type, rules) {
  const acc = (profile.ok && profile.accounts) || {};
  const r = rules.accounts;
  const fa = r.firstAccounts;
  const flags = [];
  const notes = [];
  let calc = null;

  const lastAccounts = company.lastAccounts || acc.lastMadeUpTo || null;
  const incorporated = company.incorporated || (profile.ok ? profile.incorporated : null) || null;
  const needCalc = !acc.nextDue && !company.accountsDueOverride;

  if (needCalc) {
    let periodEnd = acc.nextMadeUpTo || company.periodEnd || null;
    if (!periodEnd && lastAccounts) {
      const next = addMonths(lastAccounts, r.standardPeriodMonths, true);
      periodEnd = next.date;
      flags.push(`Next accounting period end assumed to be ${r.standardPeriodMonths} months after the last accounts (${lastAccounts}). A changed accounting reference date would make this wrong. Needs human confirmation.`);
    }
    const first = !lastAccounts;
    if (!periodEnd && first && incorporated) {
      // The first accounting reference date is the last day of the month in which
      // the first anniversary of incorporation falls.
      const anniversary = addMonths(incorporated, 12, false);
      if (anniversary.clamped) flags.push('Incorporated on 29 February: the first anniversary is taken as 28 February. Needs human confirmation.');
      periodEnd = anniversary.date ? lastDayOfMonthOf(anniversary.date) : null;
      notes.push('First accounting reference date taken as the last day of the month of the first anniversary of incorporation.');
    }

    if (!type) {
      flags.push('Company type (private or public) is not known, so the accounts period cannot be applied. Needs human confirmation.');
    } else if (!periodEnd) {
      flags.push('No accounting period end, last accounts date or incorporation date to work from. Needs human confirmation.');
    } else if (first && !incorporated) {
      flags.push('First accounts: the incorporation date is needed to apply the first-accounts rule. Needs human confirmation.');
    } else {
      const normalMonths = type === 'public' ? r.publicMonthsAfterPeriodEnd : r.privateMonthsAfterPeriodEnd;
      let due = addMonths(periodEnd, normalMonths, true);
      if (first) {
        if (/-02-29$/.test(incorporated)) {
          flags.push('Incorporated on 29 February: the first-accounts deadline depends on how the first anniversary (28 February or 1 March) is treated, and the kit works from the incorporation date. Needs human confirmation.');
        }
        const anniversary = addMonths(incorporated, r.standardPeriodMonths, false).date;
        const periodOverTwelveMonths = anniversary !== null && periodEnd >= anniversary;
        if (periodOverTwelveMonths) {
          const fromInc = addMonths(incorporated, type === 'public' ? fa.publicMonthsAfterIncorporation : fa.privateMonthsAfterIncorporation, false);
          const fromEnd = addMonths(periodEnd, fa.minimumMonthsAfterPeriodEnd, true);
          if (fromInc.date && fromEnd.date) {
            const useInc = fromInc.date >= fromEnd.date;
            due = useInc ? fromInc : fromEnd;
            notes.push('First accounts covering more than 12 months: the longer of the months after incorporation and 3 months after the period end.');
          }
        }
      }
      if (due.clamped) flags.push('The corresponding date does not exist in the deadline month, so the last day of that month was used. The guidance does not cover this case. Needs human confirmation.');
      calc = { date: due.date, periodEnd, flags, notes };
    }
    if (!calc) calc = { date: null, periodEnd, flags, notes };
  }

  return choose('accounts', acc.nextDue || null, company.accountsDueOverride, calc,
    acc.nextMadeUpTo || company.periodEnd || (calc && calc.periodEnd) || null, acc.overdue);
}

/**
 * Confirmation statement deadline. The first review period is the 12 months
 * beginning with the day of incorporation, so it ends the day before the first
 * anniversary; later ones start the day after the previous confirmation date and
 * last 12 months. The statement can be filed up to 14 days after the period ends.
 */
function confirmationDeadline(company, profile, rules) {
  const cs = (profile.ok && profile.confirmationStatement) || {};
  const r = rules.confirmationStatement;
  let calc = null;
  const needCalc = !cs.nextDue && !company.csDueOverride;

  if (needCalc) {
    const flags = [];
    const notes = [];
    let reviewEnd = cs.nextMadeUpTo || null;
    if (!reviewEnd) {
      const last = company.lastCs || cs.lastMadeUpTo || null;
      const incorporated = company.incorporated || (profile.ok ? profile.incorporated : null) || null;
      if (last) {
        // Later statements (s853A(5)(b) and (6)): the next review period starts the day
        // after the last confirmation date and lasts 12 months, so it ends on the day
        // before that start's anniversary. `last` must be the confirmation date on the
        // last statement, not its due date or filing date.
        const start = addDays(last, 1);
        const anniversary = start ? addMonths(start, r.reviewPeriodMonths, false) : { date: null };
        if (anniversary.clamped) {
          // A period beginning on 29 February: the statute does not say how it ends.
          // It is taken to end on 28 February, as for a first period (see R-14).
          flags.push('The review period begins on 29 February, so its end was taken as 28 February. Needs human confirmation.');
          reviewEnd = anniversary.date;
        } else {
          reviewEnd = anniversary.date ? addDays(anniversary.date, -1) : null;
        }
      } else if (incorporated) {
        // First statement: the 12 months begin on the day of incorporation (s853A(5)(a)),
        // so the period ends the day before the first anniversary.
        const anniversary = addMonths(incorporated, r.reviewPeriodMonths, false);
        if (anniversary.clamped) {
          flags.push('Incorporated on 29 February: the review period end was taken as 28 February. Needs human confirmation.');
          reviewEnd = anniversary.date;
        } else {
          reviewEnd = anniversary.date ? addDays(anniversary.date, -1) : null;
        }
      } else {
        flags.push('No last confirmation date or incorporation date to work from. Needs human confirmation.');
      }
    }
    if (reviewEnd) {
      const due = addDays(reviewEnd, r.filingDaysAfterReviewPeriodEnd);
      calc = { date: due, periodEnd: reviewEnd, flags, notes };
    } else {
      calc = { date: null, periodEnd: null, flags, notes };
    }
  }

  return choose('confirmationStatement', cs.nextDue || null, company.csDueOverride, calc,
    cs.nextMadeUpTo || (calc && calc.periodEnd) || null, cs.overdue);
}

// ---- copy.js ----
// Wording. Plain text, UK English, no emoji. Everything addressed to the
// practice is a digest; anything addressed to a client is a draft that a person
// reads and sends from their own mailbox. This kit sends no client email.


const REGISTER_URL = 'https://find-and-update.company-information.service.gov.uk/company/';

function dueWords(days) {
  if (days < 0) return `${-days} day${days === -1 ? '' : 's'} OVERDUE`;
  if (days === 0) return 'due today';
  if (days === 1) return 'due tomorrow';
  return `due in ${days} days`;
}

function sourceLabel(source) {
  if (source === 'companies-house') return 'Companies House';
  if (source === 'sheet') return 'typed into your sheet';
  if (source === 'calculated') return 'calculated from your sheet';
  return 'unknown';
}

/** A draft message for a person to review and send. Never sent by the workflow. */
function buildClientDraft(item, config) {
  const plural = item.kind === 'accounts';
  const what = plural ? 'annual accounts' : 'confirmation statement';
  const was = plural ? 'were' : 'was';
  const is = plural ? 'are' : 'is';
  const lines = [
    `Subject: ${item.companyName || 'Your company'}: ${what} due ${formatUKDate(item.dueDate)}`,
    '',
    ...(item.needsConfirmation ? ['[STAFF: this date has not been confirmed against the Companies House register. Confirm it, then delete this line, before sending.]', ''] : []),
    'Dear client,',
    '',
    item.days < 0
      ? `Our records show that the ${what} for ${item.companyName || 'your company'} (company number ${item.companyNumber}) ${was} due on ${formatUKDate(item.dueDate)} and may now be overdue.`
      : `Our records show that the ${what} for ${item.companyName || 'your company'} (company number ${item.companyNumber}) ${is} due at Companies House on ${formatUKDate(item.dueDate)}.`,
    '',
    item.days < 0
      ? 'Please get in touch as soon as you can so that we can arrange what is needed.'
      : 'Please get in touch as soon as you can so that we can arrange what is needed before the deadline.',
    '',
    'Kind regards,',
    config.firmName || 'Your Firm',
  ];
  return lines.join('\n');
}

function buildDigest({ reminders, attention, runDate, config, summary }) {
  const prefix = config.dryRun ? '[DRY RUN] ' : '';
  const needCheck = reminders.filter((r) => r.needsConfirmation).length;
  const subject = `${prefix}Companies House deadlines: ${reminders.length} reminder${reminders.length === 1 ? '' : 's'}`
    + `${attention.length ? `, ${attention.length} to check` : ''} (${formatUKDate(runDate)})`;

  const out = [];
  if (config.dryRun) {
    out.push('DRY RUN. This is a preview. Nothing has been recorded, so the same reminders will appear again until dry run is switched off.');
  }
  out.push('Nothing has been filed with Companies House and nothing has been sent to any client. This is a list for your team to act on.');
  out.push('');

  out.push(`REMINDERS (${reminders.length})`);
  if (reminders.length === 0) out.push('None today.');
  for (const r of reminders) {
    out.push('');
    out.push(`${r.companyName || '(no name)'} (${r.companyNumber}) - ${KIND_LABEL[r.kind]}`);
    out.push(`  Deadline: ${formatUKDate(r.dueDate)}, ${dueWords(r.days)}`);
    out.push(`  Date from: ${sourceLabel(r.source)}`);
    out.push(`  Check on the register: ${REGISTER_URL}${r.companyNumber}`);
    if (r.needsConfirmation) {
      for (const f of r.flags) out.push(`  NEEDS HUMAN CONFIRMATION: ${f}`);
    }
    if (r.draft) {
      out.push('  Draft client message (not sent, edit before use):');
      out.push(`  To: ${r.draftTo || '(no valid contact email in the sheet)'}`);
      for (const line of r.draft.split('\n')) out.push(`  | ${line}`);
    }
  }

  if (attention.length) {
    out.push('');
    out.push(`NEEDS YOUR ATTENTION (${attention.length})`);
    for (const a of attention) {
      out.push(`- ${a.companyName || '(no name)'}${a.companyNumber ? ` (${a.companyNumber})` : ''}: ${a.reason}`);
    }
  }

  out.push('');
  out.push(`Checked ${summary.rowsRead} row${summary.rowsRead === 1 ? '' : 's'}; ${summary.skipped} not reminded (paused, not yet in a reminder window, already reminded or no longer on the register).`);
  if (needCheck) out.push(`${needCheck} reminder${needCheck === 1 ? '' : 's'} above need${needCheck === 1 ? 's' : ''} human confirmation before anyone relies on the date.`);
  if (config.configWarnings && config.configWarnings.length) {
    out.push('');
    for (const w of config.configWarnings) out.push(`Configuration note: ${w}`);
  }
  out.push('');
  out.push('Deadlines are worked out from published GOV.UK guidance and the Companies House record. They are not legal advice. Confirm on the register before relying on any date.');
  return { subject, body: out.join('\n') };
}

// ---- config.js ----
/**
 * Defaults for the tracker. Everything a practice would reasonably want to
 * change lives here, is passed in from the workflow's Build Config node, and is
 * covered by tests. Nothing behavioural is read from the environment directly.
 * The statutory numbers are not here: they are in rules/deadline-rules.json.
 */
const DEFAULT_CONFIG = {
  // Days before a deadline at which a reminder is raised.
  milestones: [30, 14, 7, 1],

  // Once a deadline has passed, remind again every this many days.
  overdueRepeatDays: 7,

  // Day of the week (0 = Sunday, 1 = Monday) on which a digest is sent even if
  // no reminder is due, so rows that need checking are not left for ever.
  // null switches this off.
  attentionDigestWeekday: 1,

  firmName: 'Your Firm',

  // The reminder digest goes to the practice, never to a client.
  practiceEmail: '',
  senderEmail: 'accounts@example.co.uk',

  // Add a draft client message under each reminder, for the practice to read
  // and send itself. The kit never sends it.
  includeClientDrafts: true,

  // Safety. While true, the digest is labelled as a preview, goes to
  // dryRunRecipient (or the practice mailbox) and nothing is recorded in the
  // Sent Log, so switching it off later does not lose a single reminder.
  dryRun: true,
  dryRunRecipient: '',

  rules: {
  "validAsOf": "2026-10-05",
  "sources": {
    "accountsGuidance": "https://www.gov.uk/government/publications/filing-your-companies-house-accounts/life-of-a-company-part-1-accounts",
    "accountsOverview": "https://www.gov.uk/prepare-file-annual-accounts-for-limited-company",
    "confirmationStatementGuidance": "https://www.gov.uk/guidance/confirmation-statement-guidance"
  },
  "accounts": {
    "privateMonthsAfterPeriodEnd": 9,
    "publicMonthsAfterPeriodEnd": 6,
    "standardPeriodMonths": 12,
    "firstAccounts": {
      "privateMonthsAfterIncorporation": 21,
      "publicMonthsAfterIncorporation": 18,
      "minimumMonthsAfterPeriodEnd": 3
    }
  },
  "confirmationStatement": {
    "reviewPeriodMonths": 12,
    "filingDaysAfterReviewPeriodEnd": 14
  },
  "companyStatus": {
    "remindFor": ["active"],
    "suppress": ["dissolved", "closed", "converted-closed", "removed"]
  },
  "companyType": {
    "private": ["ltd", "private", "private limited", "private limited company", "limited", "private-ltd"],
    "public": ["plc", "public", "public limited", "public limited company"]
  },
  "api": {
    "baseUrl": "https://api.company-information.service.gov.uk",
    "requestsPerFiveMinutes": 600
  }
},
};

function sanitiseMilestones(value, warnings) {
  const ok = Array.isArray(value)
    && value.length > 0
    && value.every((n) => Number.isInteger(n) && n >= 1 && n <= 366);
  if (!ok) {
    warnings.push('Reminder milestones were not a list of whole numbers of days, so the defaults were used.');
    return [...DEFAULT_CONFIG.milestones];
  }
  return [...new Set(value)].sort((a, b) => b - a);
}

function withDefaults(config) {
  const given = config && typeof config === 'object' ? config : {};
  const warnings = [];
  const merged = { ...DEFAULT_CONFIG, ...given };
  merged.milestones = sanitiseMilestones(given.milestones === undefined ? DEFAULT_CONFIG.milestones : given.milestones, warnings);
  if (!Number.isInteger(merged.overdueRepeatDays) || merged.overdueRepeatDays < 1) {
    warnings.push('overdueRepeatDays was not a positive whole number, so 7 was used.');
    merged.overdueRepeatDays = 7;
  }
  const wd = merged.attentionDigestWeekday;
  if (wd !== null && !(Number.isInteger(wd) && wd >= 0 && wd <= 6)) {
    warnings.push('attentionDigestWeekday must be 0 to 6 or null, so Monday was used.');
    merged.attentionDigestWeekday = 1;
  }
  // Only the exact boolean false turns the safety off.
  merged.dryRun = merged.dryRun !== false;
  merged.includeClientDrafts = merged.includeClientDrafts !== false;
  merged.rules = given.rules && typeof given.rules === 'object' ? given.rules : DEFAULT_CONFIG.rules;
  merged.configWarnings = warnings;
  return merged;
}

// ---- plan.js ----
// The one decision function. Given the sheet rows with whatever Companies House
// returned for each, the run date, the config and the keys of reminders already
// logged, it returns everything the workflow needs: the digest, the rows to log
// and a summary. It performs no I/O, reads no n8n globals and never throws.
// Anything it cannot handle comes back in `attention`, not as an exception.






function emptySummary(runDate, cfg) {
  return {
    runDate: runDate || null,
    rowsRead: 0,
    emptyRows: 0,
    reminders: 0,
    attention: 0,
    skipped: 0,
    lookupFailures: 0,
    lookupsAttempted: 0,
    lookupsAllFailed: false,
    failRun: false,
    failReason: '',
    dryRun: cfg.dryRun,
    halted: false,
    haltReason: '',
    digestTo: '',
    sendDigest: false,
  };
}

function halted(runDate, cfg, reason) {
  const summary = emptySummary(runDate, cfg);
  summary.halted = true;
  summary.haltReason = reason;
  summary.failRun = true;
  summary.failReason = reason;
  return { summary, reminders: [], attention: [], skipped: [], sentLogRows: [], digest: { subject: '', body: '' } };
}

function keyFor(number, kind, dueDate, band) {
  return `${number}|${kind}|${dueDate}|${band}`;
}

function evaluateCompany(entry, ctx) {
  const { today, cfg, sentSet, seenNumbers, out } = ctx;
  const rowObj = entry && typeof entry === 'object' && entry.row && typeof entry.row === 'object' ? entry.row : null;

  if (!rowObj || isEmptyRow(rowObj)) { out.summary.emptyRows += 1; return; }
  out.summary.rowsRead += 1;

  const rules = cfg.rules;
  const company = readCompanyRow(rowObj, rules);
  const who = { companyName: company.name, companyNumber: company.number.number };
  const attend = (reason) => out.attention.push({ ...who, reason });
  const skip = (reason) => out.skipped.push({ ...who, reason });

  if (company.paused) { skip('paused in the sheet'); return; }
  for (const p of company.problems) attend(p);

  if (!company.number.valid) {
    attend(`${company.number.reason}. Needs human confirmation.`);
    skip('no usable company number');
    return;
  }
  if (seenNumbers.has(company.number.number)) {
    attend('appears more than once in the sheet; only the first row is used');
    skip('duplicate company number');
    return;
  }
  seenNumbers.add(company.number.number);
  if (company.number.padded) {
    attend(`company number was padded with leading zeros to ${company.number.number}; fix the column format in the sheet so it is stored as text`);
  }

  if (entry.api !== null && entry.api !== undefined) out.summary.lookupsAttempted += 1;
  let profile = readApiProfile(entry.api);
  if (profile.ok && profile.number !== company.number.number) {
    // A response for a different company (or with no number) must never be applied.
    profile = { ok: false, reason: `Companies House returned ${profile.number ? `number ${profile.number}` : 'no company number'}, not ${company.number.number}, so the response was discarded` };
  }
  if (!profile.ok) {
    out.summary.lookupFailures += 1;
    attend(`${profile.reason}. Using the sheet only; deadlines are not cross-checked.`);
  } else {
    const action = statusAction(profile.status, rules);
    if (action === 'suppress') { skip(`company status is ${profile.status}`); return; }
    if (action === 'review') {
      attend(`company status is "${profile.status || 'unknown'}", so no reminders are raised. Needs human confirmation.`);
      skip('company status needs review');
      return;
    }
  }

  let type = company.type;
  if (profile.ok && profile.type) {
    if (company.type && company.type !== profile.type) {
      attend(`sheet says ${company.type} but Companies House says ${profile.type}; Companies House is used. Needs human confirmation.`);
    }
    type = profile.type;
  } else if (profile.ok && !company.type) {
    attend(`Companies House company type "${profile.rawType || 'unknown'}" is not one this kit applies accounts rules to. Needs human confirmation.`);
  }

  const name = company.name || (profile.ok ? profile.name : '');
  const deadlines = [
    accountsDeadline(company, profile, type, rules),
    confirmationDeadline(company, profile, rules),
  ];

  let reminded = 0;
  for (const d of deadlines) {
    if (!d.dueDate) {
      attend(`${d.kind === 'accounts' ? 'Accounts' : 'Confirmation statement'} deadline could not be worked out: ${d.flags.join(' ')}`);
      continue;
    }
    if (d.discrepancy) attend(`${d.kind === 'accounts' ? 'Accounts' : 'Confirmation statement'}: ${d.flags[0]}`);
    const days = daysBetween(today, d.dueDate);
    const band = bandFor(days, cfg.milestones, cfg.overdueRepeatDays);
    if (!band) continue;
    const key = keyFor(company.number.number, d.kind, d.dueDate, band.band);
    if (sentSet.has(key)) continue;
    const item = {
      companyName: name,
      companyNumber: company.number.number,
      kind: d.kind,
      dueDate: d.dueDate,
      days,
      band: band.band,
      overdue: band.overdue,
      source: d.source,
      flags: d.flags,
      needsConfirmation: d.needsConfirmation,
      idempotencyKey: key,
      draft: '',
      draftTo: '',
    };
    if (cfg.includeClientDrafts) {
      item.draft = buildClientDraft(item, cfg);
      item.draftTo = isValidEmail(company.email) ? company.email : '';
    }
    out.reminders.push(item);
    reminded += 1;
  }
  if (reminded === 0) skip('no deadline is in a reminder window, or already reminded');
}

/**
 * Reads the idempotency keys out of Sent Log rows. If the log has content but no
 * key can be found (a renamed header, say) it reports a problem instead of
 * returning an empty list, which would repeat every reminder every day.
 * Returns { keys, problem }; problem is '' when the log is fine or truly empty.
 */
function sentLogKeys(rows) {
  const list = Array.isArray(rows) ? rows : [];
  const keys = list
    .map((r) => String(r && typeof r === 'object' ? (r['Idempotency Key'] ?? '') : '').trim())
    .filter(Boolean);
  const hasContent = list.some((r) => r && typeof r === 'object'
    && Object.entries(r).some(([k, v]) => k !== 'row_number' && String(v ?? '').trim() !== ''));
  if (hasContent && keys.length === 0) {
    return { keys, problem: 'the Sent Log has data but no "Idempotency Key" column was found. Check the header spelling against templates/Sent Log.csv' };
  }
  return { keys, problem: '' };
}

/**
 * @param {object} input
 * @param {Array<{row: object, api: object|null}>} input.companies
 * @param {string} input.today  'YYYY-MM-DD' in Europe/London
 * @param {object} input.config
 * @param {string[]} input.sentKeys  idempotency keys already in the Sent Log
 */
function plan(input) {
  let cfg = withDefaults(null);
  try {
    const { companies, today, config, sentKeys } = input && typeof input === 'object' ? input : {};
    cfg = withDefaults(config);

    if (tsOf(today) === null) return halted(today, cfg, `the run date "${String(today)}" is not a valid date`);
    const problems = rulesProblems(cfg.rules);
    if (problems.length) return halted(today, cfg, problems.join('; '));

    const out = {
      summary: emptySummary(today, cfg),
      reminders: [],
      attention: [],
      skipped: [],
      sentLogRows: [],
      digest: { subject: '', body: '' },
    };
    const sentSet = new Set((Array.isArray(sentKeys) ? sentKeys : []).map((k) => String(k ?? '').trim()).filter(Boolean));
    const seenNumbers = new Set();
    const list = Array.isArray(companies) ? companies : [];

    for (const entry of list) {
      try {
        evaluateCompany(entry, { today, cfg, sentSet, seenNumbers, out });
      } catch (err) {
        out.attention.push({
          companyName: '',
          companyNumber: '',
          reason: 'a row could not be processed and was skipped. Needs human confirmation.',
        });
      }
    }

    out.reminders.sort((a, b) => a.days - b.days
      || a.companyNumber.localeCompare(b.companyNumber)
      || a.kind.localeCompare(b.kind));
    out.skipped.sort((a, b) => a.companyNumber.localeCompare(b.companyNumber));

    const s = out.summary;
    if (s.lookupsAttempted > 0 && s.lookupFailures >= s.lookupsAttempted) {
      s.lookupsAllFailed = true;
      s.failRun = true;
      s.failReason = 'every Companies House lookup failed (check the API key and credential); dates came from the sheet only';
    }
    if (s.rowsRead === 0) {
      // An empty or wrong Companies tab, or a wrong sheet id, must not look like a quiet day.
      out.attention.push({ companyName: '', companyNumber: '', reason: 'no company rows were read. Check the Companies tab name, its headers and the sheet id.' });
      s.failRun = true;
      s.failReason = s.failReason || 'no company rows were read (check the Companies tab, its headers and the sheet id)';
    }
    s.reminders = out.reminders.length;
    s.attention = out.attention.length;
    s.skipped = out.skipped.length;

    const to = cfg.dryRun ? (cfg.dryRunRecipient || cfg.practiceEmail) : cfg.practiceEmail;
    s.digestTo = isValidEmail(to) ? String(to).trim() : '';
    const weekdayHit = cfg.attentionDigestWeekday !== null && dayOfWeek(today) === cfg.attentionDigestWeekday;
    const worthSending = out.reminders.length > 0 || (out.attention.length > 0 && weekdayHit);
    if (worthSending && !s.digestTo) {
      s.halted = true;
      s.haltReason = 'there is something to report but no valid practice email address is configured';
      s.failRun = true;
      s.failReason = s.haltReason;
    }
    s.sendDigest = worthSending && s.digestTo !== '';

    if (s.sendDigest) {
      out.digest = buildDigest({
        reminders: out.reminders, attention: out.attention, runDate: today, config: cfg, summary: s,
      });
      // Dry run records nothing, so that going live later loses no reminder.
      if (!cfg.dryRun) {
        out.sentLogRows = out.reminders.map((r) => ({
          'Idempotency Key': r.idempotencyKey,
          'Company Number': r.companyNumber,
          'Company Name': r.companyName,
          'Deadline Type': r.kind,
          'Due Date': r.dueDate,
          Band: r.band,
          'Reported On': today,
        }));
      }
    }
    return out;
  } catch (err) {
    return halted(input && input.today, cfg, 'unexpected error while planning; nothing was sent');
  }
}

